using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace VinsPDF {
internal sealed class ExportOptions : StyledDialog {
 readonly ComboBox format=new DarkComboBox(),pages=new DarkComboBox();readonly TextBox range=new TextBox();readonly NumericUpDown dpi=new NumericUpDown(),quality=new NumericUpDown();readonly CheckBox grey=new CheckBox{ForeColor=Color.Gainsboro};readonly Label note=new Label();readonly int count,current;
 public int Kind{get{return format.SelectedIndex;}}public int Dpi{get{return (int)dpi.Value;}}public int Quality{get{return (int)quality.Value;}}public bool Grey{get{return grey.Checked;}}public string Extension{get{return new[]{"pdf","pdf","png","jpg","tif","bmp"}[Kind];}}
 public int[] Order{get{return pages.SelectedIndex==0?Enumerable.Range(0,count).ToArray():pages.SelectedIndex==1?new[]{current}:PdfEngine.PageRange(range.Text,count);}}
 public ExportOptions(int pageCount,int currentPage):base("Export PDF / images",448,397){count=pageCount;current=currentPage;var p=new Panel{Dock=DockStyle.Fill,Padding=new Padding(12)};Controls.Add(p);Field(p,"Format",format,12);format.Items.AddRange(new object[]{"PDF · original quality (editable)","PDF · reduced size (flattened)","PNG image · lossless","JPEG image · compressed","TIFF image · lossless","BMP image · uncompressed"});Field(p,"Pages",pages,50);pages.Items.AddRange(new object[]{"All pages","Current page","Custom range"});Field(p,"Page range",range,88);range.Text="1-"+count;Field(p,"Resolution · dpi",dpi,126);dpi.Minimum=36;dpi.Maximum=600;dpi.Value=96;Field(p,"JPEG quality · %",quality,164);quality.Minimum=10;quality.Maximum=100;quality.Value=85;grey.Text="Greyscale";grey.SetBounds(150,202,270,26);p.Controls.Add(grey);note.SetBounds(14,239,403,66);note.ForeColor=Color.Silver;p.Controls.Add(note);var export=ActionButton("Export…",delegate{try{var check=Order;DialogResult=DialogResult.OK;}catch(Exception ex){DarkMessage.Show(this,ex.Message,"Page range");}});export.SetBounds(196,313,108,30);var cancel=ActionButton("Cancel",delegate{DialogResult=DialogResult.Cancel;});cancel.SetBounds(312,313,108,30);p.Controls.AddRange(new Control[]{export,cancel});AcceptButton=export;CancelButton=cancel;format.SelectedIndexChanged+=delegate{RefreshOptions();};pages.SelectedIndexChanged+=delegate{RefreshOptions();};format.SelectedIndex=0;pages.SelectedIndex=0;Ready();}
 void Field(Panel p,string label,Control c,int y){p.Controls.Add(new Label{Text=label,Left=14,Top=y+5,Width=132,Height=24,ForeColor=Color.Gainsboro});c.SetBounds(150,y,270,26);c.BackColor=Color.FromArgb(29,34,39);c.ForeColor=Color.White;if(c is ComboBox){var cb=(ComboBox)c;cb.DropDownStyle=ComboBoxStyle.DropDownList;cb.FlatStyle=FlatStyle.Flat;cb.DrawMode=DrawMode.OwnerDrawFixed;cb.DrawItem+=delegate(object s,DrawItemEventArgs e){using(var b=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(46,71,91):Color.FromArgb(29,34,39)))e.Graphics.FillRectangle(b,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,cb.Items[e.Index].ToString(),cb.Font,e.Bounds,Color.White,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};}p.Controls.Add(c);}
 internal void PreviewFormat(int kind){format.SelectedIndex=kind;}
 void RefreshOptions(){range.Enabled=pages.SelectedIndex==2;dpi.Enabled=Kind!=0;grey.Visible=Kind!=0;quality.Enabled=Kind==1||Kind==3;note.Text=Kind==0?"Keeps vectors and editable text. Exporting a page subset may omit document-level bookmarks and forms.":"One image per page, or a flattened image PDF. Text will not be selectable. Maximum 24 megapixels per page; use a lower dpi for large drawings.";}
}
internal sealed partial class PdfEngine {
 public Size ExportPixelSize(int index,int dpi){if(dpi<36||dpi>600)throw new IOException("Choose a resolution from 36 to 600 dpi.");int w=Math.Max(1,(int)Math.Round(Sizes[index].Width*dpi/72)),h=Math.Max(1,(int)Math.Round(Sizes[index].Height*dpi/72));if((long)w*h>24000000)throw new IOException("Page "+(index+1)+" is too large at "+dpi+" dpi. Choose a lower resolution (maximum 24 megapixels per page).");return new Size(w,h);}
 Bitmap ExportBitmap(int index,int dpi,bool grey){Size s=ExportPixelSize(index,dpi);Bitmap image=Render(index,0,s.Width,s.Height,0,0,s.Width,s.Height);image.SetResolution(dpi,dpi);if(!grey)return image;var result=new Bitmap(s.Width,s.Height,PixelFormat.Format24bppRgb);result.SetResolution(dpi,dpi);using(var g=Graphics.FromImage(result))using(var attr=new ImageAttributes()){var m=new ColorMatrix(new[]{new[]{.299f,.299f,.299f,0,0},new[]{.587f,.587f,.587f,0,0},new[]{.114f,.114f,.114f,0,0},new[]{0f,0,0,1,0},new[]{0f,0,0,0,1}});attr.SetColorMatrix(m);g.DrawImage(image,new Rectangle(Point.Empty,s),0,0,s.Width,s.Height,GraphicsUnit.Pixel,attr);}image.Dispose();return result;}
 static void SaveJpeg(Bitmap image,Stream stream,int quality){var codec=ImageCodecInfo.GetImageEncoders().First(c=>c.MimeType=="image/jpeg");using(var pars=new EncoderParameters(1)){pars.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,(long)quality);image.Save(stream,codec,pars);}}
 public static string[] ImageTargets(string target,int[] order){return order.Length==1?new[]{target}:order.Select((p,i)=>Path.Combine(Path.GetDirectoryName(target),Path.GetFileNameWithoutExtension(target)+"-"+(i+1).ToString("D3")+"-p"+(p+1).ToString("D3")+Path.GetExtension(target))).ToArray();}
 public void ExportImages(string target,int[] order,string extension,int dpi,int quality,bool grey){if(order.Length==0)throw new IOException("Choose at least one page.");foreach(int i in order)ExportPixelSize(i,dpi);PrepareExport();var targets=ImageTargets(target,order);for(int n=0;n<order.Length;n++){string temp=targets[n]+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var image=ExportBitmap(order[n],dpi,grey))using(var stream=new FileStream(temp,FileMode.CreateNew)){if(extension=="jpg")SaveJpeg(image,stream,quality);else image.Save(stream,extension=="png"?ImageFormat.Png:extension=="tif"?ImageFormat.Tiff:ImageFormat.Bmp);}if(File.Exists(targets[n]))File.Replace(temp,targets[n],null);else File.Move(temp,targets[n]);}finally{if(File.Exists(temp))File.Delete(temp);}}}
 public void ExportReduced(string target,int[] order,int dpi,int quality,bool grey){if(order.Length==0)throw new IOException("Choose at least one page.");foreach(int i in order)ExportPixelSize(i,dpi);PrepareExport();using(var dest=new PdfEngine()){dest.document=Native.FPDF_CreateNewDocument();for(int n=0;n<order.Length;n++){int i=order[n];using(var image=ExportBitmap(i,dpi,grey))using(var jpeg=new MemoryStream()){SaveJpeg(image,jpeg,quality);byte[] bytes=jpeg.ToArray();Native.GetBlock read=delegate(IntPtr param,uint offset,IntPtr buffer,uint length){if((ulong)offset+length>(ulong)bytes.Length)return 0;Marshal.Copy(bytes,(int)offset,buffer,(int)length);return 1;};var access=new Native.FileAccess{Length=(uint)bytes.Length,Read=Marshal.GetFunctionPointerForDelegate(read)};IntPtr page=Native.FPDFPage_New(dest.document,n,Sizes[i].Width,Sizes[i].Height),obj=Native.FPDFPageObj_NewImageObj(dest.document);try{Check(Native.FPDFImageObj_LoadJpegFileInline(IntPtr.Zero,0,obj,ref access)!=0,"JPEG export failed.");Native.FPDFPageObj_Transform(obj,Sizes[i].Width,0,0,Sizes[i].Height,0,0);Native.FPDFPage_InsertObject(page,obj);obj=IntPtr.Zero;Check(Native.FPDFPage_GenerateContent(page)!=0,"Page export failed.");}finally{if(obj!=IntPtr.Zero)Native.FPDFPageObj_Destroy(obj);Native.FPDF_ClosePage(page);GC.KeepAlive(read);}}}WriteDocument(dest.document,target);}}
}
internal sealed partial class MainForm {
 void ExportDocument(){using(var options=new ExportOptions(sizes.Length,pageIndex)){if(options.ShowDialog(TopLevelControl as Form??this)!=DialogResult.OK)return;int kind=options.Kind,dpi=options.Dpi,quality=options.Quality;bool grey=options.Grey;int[] order=options.Order;string ext=options.Extension;using(var picker=new SaveFileDialog{Title="Export",Filter=ext.ToUpperInvariant()+" file|*."+ext,DefaultExt=ext,AddExtension=true,OverwritePrompt=true,FileName=Path.GetFileNameWithoutExtension(currentPath)+"-export."+ext}){if(picker.ShowDialog(TopLevelControl as Form??this)!=DialogResult.OK)return;string target=picker.FileName;if(string.Equals(Path.GetFullPath(target),Path.GetFullPath(currentPath),StringComparison.OrdinalIgnoreCase)){DarkMessage.Show(this,"Choose a different name to keep the open document intact.");return;}if(kind>1&&order.Length>1){int existing=PdfEngine.ImageTargets(target,order).Count(File.Exists);if(existing>0&&DarkMessage.Show(this,"Replace "+existing+" existing exported image(s)?","Export images",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;}ToolWork("Exporting",delegate(PdfEngine e){if(kind==0){if(order.SequenceEqual(Enumerable.Range(0,e.Count)))e.ExportCopy(target);else e.ExportPages(target,order);}else if(kind==1)e.ExportReduced(target,order,dpi,quality,grey);else e.ExportImages(target,order,ext,dpi,quality,grey);},target,kind<=1);}}}
}
}
